import React, { useState, useEffect } from "react";

export default function VolunteerDonorSection() {
  // -------------------------
  // ACHIEVEMENT SYSTEM STATE
  // -------------------------
  const [achievementPoints, setAchievementPoints] = useState(0);
  const [badge, setBadge] = useState("None");

  // Auto-update badge whenever points change
  useEffect(() => {
    if (achievementPoints >= 601) setBadge("Diamond");
    else if (achievementPoints >= 301) setBadge("Gold");
    else if (achievementPoints >= 101) setBadge("Silver");
    else if (achievementPoints >= 1) setBadge("Bronze");
    else setBadge("None");
  }, [achievementPoints]);

  // -------------------------
  // BUTTON HANDLERS
  // -------------------------
  function handleDonate(points = 20) {
    setAchievementPoints(prev => prev + points);
  }

  function handleParticipate(points = 10) {
    setAchievementPoints(prev => prev + points);
  }

  // -------------------------
  // UI STARTS
  // -------------------------
  return (
    <div style={{ display: "flex", gap: "20px", padding: "20px" }}>

      {/* -----------------------------
          LEFT PANEL — ACHIEVEMENTS
      ------------------------------ */}
      <div
        style={{
          width: "30%",
          padding: "20px",
          background: "#fff",
          borderRadius: "12px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)"
        }}
      >
        <h2 style={{ marginBottom: "10px" }}>Achievements</h2>

        <p><strong>Total Points:</strong> {achievementPoints}</p>
        <p><strong>Current Badge:</strong> {badge}</p>

        <div
          style={{
            marginTop: "15px",
            padding: "12px",
            textAlign: "center",
            borderRadius: "10px",
            background:
              badge === "Diamond" ? "#b9f2ff" :
              badge === "Gold" ? "#ffd700" :
              badge === "Silver" ? "#c0c0c0" :
              badge === "Bronze" ? "#cd7f32" :
              "#eee",
            color: "#000",
            fontWeight: "bold"
          }}
        >
          {badge !== "None" ? `${badge} Badge` : "No Badge Yet"}
        </div>
      </div>

      {/* -----------------------------
          MIDDLE PANEL — DEMO BUTTONS
          You can replace this with your Events list.
      ------------------------------ */}
      <div
        style={{
          width: "40%",
          padding: "20px",
          background: "#fff",
          borderRadius: "12px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)"
        }}
      >
        <h2>Try Actions</h2>

        <button
          onClick={() => handleDonate(20)}
          style={{
            padding: "10px 15px",
            marginTop: "10px",
            cursor: "pointer",
            width: "100%"
          }}
        >
          Donate ( +20 points )
        </button>

        <button
          onClick={() => handleParticipate(10)}
          style={{
            padding: "10px 15px",
            marginTop: "10px",
            cursor: "pointer",
            width: "100%"
          }}
        >
          Participate ( +10 points )
        </button>
      </div>

      {/* -----------------------------
          RIGHT PANEL — OPTIONAL DETAILS
      ------------------------------ */}
      <div
        style={{
          width: "30%",
          padding: "20px",
          background: "#fff",
          borderRadius: "12px",
          boxShadow: "0 4px 15px rgba(0,0,0,0.1)"
        }}
      >
        <h2>Details</h2>
        <p>This section stays empty unless you want to add NGO/Event details.</p>
      </div>

    </div>
  );
}
